function isSymmetric(root: TreeNode | null): boolean {
  // Проверяет, что поддеревья a и b — зеркальные отражения друг друга
  const isMirror = (a: TreeNode | null, b: TreeNode | null): boolean => {
    // Оба пусты — зеркальны
    if (a === null && b === null) {
      return true;
    }
    // Пусто только одно — симметрии нет
    if (a === null || b === null) {
      return false;
    }
    // Значения равны, а дети сравниваются «крест-накрест»:
    // внешние (a.left и b.right) и внутренние (a.right и b.left)
    return a.val === b.val && isMirror(a.left, b.right) && isMirror(a.right, b.left);
  };

  // Дерево симметрично, если его левое поддерево — зеркало правого
  return root === null || isMirror(root.left, root.right);
}

// Время: O(n) — каждый узел участвует в одном сравнении
// Память: O(h) — стек рекурсии
